def is_one_edit_distance(s: str, t: str) -> bool:
    m, n = len(s), len(t)
    if abs(m - n) > 1:
        return False
    for i in range(min(m, n)):
        if s[i] != t[i]:
            if m == n:
                return s[i+1:] == t[i+1:]
            elif m < n:
                return s[i:] == t[i+1:]
            else:
                return s[i+1:] == t[i:]
    return abs(m - n) == 1

