def run_length_encode(s):
    if not s:
        return ""
    encoded = []
    count = 1
    prev = s[0]
    for char in s[1:]:
        if char == prev:
            count += 1
        else:
            encoded.append(f"{prev}{count}")
            prev = char
            count = 1
    encoded.append(f"{prev}{count}")
    return "".join(encoded)

